// underage check — blocks this user id from using yap++
(function () {
  let uid = null;
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.indexOf('sb-') === 0 && k.indexOf('-auth-token') !== -1) {
        let v = JSON.parse(localStorage.getItem(k));
        if (typeof v === 'string') v = JSON.parse(v);
        const tok = v && (v.access_token || (v.currentSession && v.currentSession.access_token));
        if (tok) { uid = JSON.parse(atob(tok.split('.')[1])).sub; break; }
      }
    }
  } catch (e) {}
  if (uid && uid.toLowerCase() === 'ee99d35b-814e-4c21-b130-cdbfe25de390') {
    const d = document.createElement('div');
    d.style.cssText = 'position:fixed;inset:0;background:#000;z-index:2147483647;display:flex;align-items:center;justify-content:center;text-align:center;padding:40px;';
    d.innerHTML = '<div style="font-size:48px;font-weight:900;color:#ff4b4b;line-height:1.3;text-shadow:0 0 20px rgba(255,75,75,.7);">You can\'t use yap++ because you\'re underage</div>';
    document.body.appendChild(d);
    throw new Error('[Yap++] blocked: underage');
  }
})();

window.__YAPPLUS_INTRO_B64__ = "";
// ---------- yap++ loading screen ----------
(function () {
  try {
    const old = document.getElementById('yapplus-loader');
    if (old) old.remove();
    const wrap = document.createElement('div');
    wrap.id = 'yapplus-loader';
    wrap.style.cssText = [
      'position:fixed', 'inset:0', 'z-index:2147483647',
      'background:#000', 'display:flex', 'align-items:center',
      'justify-content:center', 'overflow:hidden',
      'transition:opacity .6s ease',
    ].join(';');
    const vid = document.createElement('video');
    vid.src = 'data:video/mp4;base64,' + window.__YAPPLUS_INTRO_B64__;
    vid.autoplay = true;
    vid.muted = false;
    vid.volume = 1;
    vid.playsInline = true;
    vid.style.cssText = 'width:100%;height:100%;object-fit:contain;background:#000;';
    wrap.appendChild(vid);
    const skip = document.createElement('div');
    skip.textContent = 'click for sound';
    skip.style.cssText = 'position:absolute;bottom:24px;right:28px;color:#ffffff88;font-size:13px;letter-spacing:1px;font-family:sans-serif;cursor:pointer;text-shadow:0 0 8px #000;';
    wrap.appendChild(skip);
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      wrap.style.opacity = '0';
      setTimeout(() => { try { wrap.remove(); } catch (e) {} }, 650);
    };
    vid.addEventListener('ended', finish);
    vid.addEventListener('error', finish);
    vid.addEventListener('playing', () => {
      if (!vid.muted) skip.textContent = 'click to skip';
    });
    skip.addEventListener('click', (e) => e.stopPropagation());
    wrap.addEventListener('click', () => {
      // first click unmutes (browser gesture requirement), later clicks skip
      if (vid.muted && !done) {
        try {
          vid.muted = false;
          vid.volume = 1;
          const pu = vid.play();
          if (pu && pu.catch) pu.catch(() => {});
          skip.textContent = 'click to skip';
        } catch (e) {}
        return;
      }
      finish();
    });
    setTimeout(finish, 15000); // hard cap
    (document.body || document.documentElement).appendChild(wrap);

    // autoplay with sound; if browser blocks it, start muted then unmute on first interaction
    let unlocked = false;
    const unlock = () => {
      if (unlocked || done) return;
      unlocked = true;
      try {
        vid.muted = false;
        vid.volume = 1;
        const p2 = vid.play();
        if (p2 && p2.catch) p2.catch(() => {});
        skip.textContent = 'click to skip';
      } catch (e) {}
      window.removeEventListener('pointerdown', unlock);
      window.removeEventListener('keydown', unlock);
    };
    const p = vid.play();
    if (p && p.catch) {
      p.catch(() => {
        try {
          vid.muted = true;
          const p3 = vid.play();
          if (p3 && p3.catch) p3.catch(() => {});
        } catch (e) {}
      });
    }
    vid.addEventListener('playing', () => {
      if (vid.muted && !done) {
        window.addEventListener('pointerdown', unlock, { once: true });
        window.addEventListener('keydown', unlock, { once: true });
      }
    });
    window.addEventListener('pointerdown', unlock, { once: true });
    window.addEventListener('keydown', unlock, { once: true });
  } catch (e) {}
})();


const PluginHost = {
  plugins: [],
  listeners: [],
  register(plugin) {
    this.plugins.push(plugin);
    if (localStorage.getItem(`yapplus.plugin.${plugin.id}`) === '1') {
      try { plugin.start(); } catch (e) { console.error('[Yap++] start failed', plugin.id, e); }
    }
    this.listeners.forEach(fn => fn(plugin));
  },
  isEnabled(plugin) {
    return localStorage.getItem(`yapplus.plugin.${plugin.id}`) === '1';
  },
  setEnabled(plugin, on) {
    localStorage.setItem(`yapplus.plugin.${plugin.id}`, on ? '1' : '0');
    try {
      on ? plugin.start() : plugin.stop();
    } catch (e) { console.error('[Yap++] toggle failed', plugin.id, e); }
    this.listeners.forEach(fn => fn(plugin));
  },
  all() { return this.plugins.slice(); },
  onChange(fn) { this.listeners.push(fn); },
};

