const messagelogger = {
  id: 'messagelogger',
  name: 'MessageLogger',
  description: 'Logs messages with name and pfp. Deleted messages stay visible in red.',
  _obs: null,
  _timer: null,
  _delay: null,

  currentChannelId() {
    try {
      const p = JSON.parse(localStorage.getItem('yapper:place') || '{}');
      if (p.c) return p.c;
    } catch (e) {}
    try {
      const m = location.href.match(/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i);
      if (m) return m[1];
    } catch (e) {}
    return null;
  },

  store() {
    try { return JSON.parse(localStorage.getItem('yapplus.mlog') || '{}'); } catch (e) { return {}; }
  },
  persist(d) {
    try {
      const arr = Object.values(d).filter(r => r && r.t);
      if (arr.length > 900) {
        arr.sort((a, b) => b.t - a.t);
        for (const r of arr.slice(900)) delete d[r.id];
      }
      localStorage.setItem('yapplus.mlog', JSON.stringify(d));
    } catch (e) {}
  },

  capture(id, el) {
    const d = this.store();
    const old = d[id] || {};
    const txt = el.querySelector('.msg-text');
    const au = el.querySelector('.msg-author');
    const im = el.querySelector('.avatar img');
    const tm = el.querySelector('.msg-time');
    d[id] = {
      id,
      ch: old.ch || this.currentChannelId(),
      content: (txt && txt.textContent) || old.content || '',
      name: (au && au.textContent.trim()) || old.name || '',
      pfp: (im && im.getAttribute('src')) || old.pfp || null,
      time: (tm && tm.textContent) || old.time || '',
      t: old.t || Date.now(),
      del: old.del || false,
      delAt: old.delAt || null,
    };
    this.persist(d);
  },

  markDeleted(id) {
    const d = this.store();
    const r = d[id];
    if (!r || r.del) return;
    r.del = true;
    r.delAt = Date.now();
    this.persist(d);
    this.render();
    this.paintGhosts();
  },

  buildGhost(r) {
    const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const el = document.createElement('div');
    el.className = 'msg';
    el.setAttribute('data-yp-ghost', '1');
    el.setAttribute('data-message-id', r.id);
    const av = r.pfp
      ? '<span class="avatar-clip" style="position:absolute;inset:0;border-radius:50%;overflow:hidden;"><img alt="" draggable="false" src="' + esc(r.pfp) + '" style="width:100%;height:100%;object-fit:cover;"></span>'
      : '<div style="width:40px;height:40px;border-radius:50%;background:#ff4b4b;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;">?</div>';
    el.innerHTML =
      '<div class="msg-gutter"><button type="button" class="avatar" style="position:relative;width:40px;height:40px;background:transparent;padding:0;border:none;cursor:default;">' + av + '</button></div>' +
      '<div class="msg-body"><div class="msg-head">' +
      '<button class="msg-author" style="color:#ff4b4b;cursor:default;">' + esc(r.name || 'unknown') + '</button>' +
      '<span class="msg-time">' + esc(r.time || '') + '</span></div>' +
      '<div class="msg-text" style="color:#ff4b4b !important;">' + esc(r.content) + '</div></div>';
    return el;
  },

  paintGhosts() {
    const list = document.querySelector('.messages');
    if (!list) return;
    const ch = this.currentChannelId();
    const d = this.store();
    const ghosts = Object.values(d).filter(r => r && r.del && r.ch === ch);
    // remove ghosts that are no longer in the log
    list.querySelectorAll('[data-yp-ghost]').forEach(el => {
      const id = el.getAttribute('data-message-id');
      if (!ghosts.find(g => g.id === id)) el.remove();
    });
    for (const g of ghosts) {
      if (list.querySelector('.msg[data-message-id="' + g.id + '"]')) continue;
      const el = this.buildGhost(g);
      const real = [...list.querySelectorAll('.msg[data-message-id]:not([data-yp-ghost])')];
      let insertBefore = null;
      for (const rn of real) {
        const rid = rn.getAttribute('data-message-id');
        const rr = d[rid];
        if (rr && rr.t && g.t && rr.t > g.t) { insertBefore = rn; break; }
      }
      if (insertBefore) insertBefore.parentNode.insertBefore(el, insertBefore);
      else if (real.length) {
        const last = real[real.length - 1];
        last.parentNode.insertBefore(el, last.nextSibling);
      } else {
        const inner = list.querySelector('div') || list;
        inner.appendChild(el);
      }
    }
  },


  forEachId(node, cb) {
    if (!node || node.nodeType !== 1) return;
    if (node.matches && node.matches('.msg[data-message-id]')) {
      const id = node.getAttribute('data-message-id');
      if (id) cb(id);
    }
    if (node.querySelectorAll) {
      node.querySelectorAll('.msg[data-message-id]').forEach(el => {
        const id = el.getAttribute('data-message-id');
        if (id) cb(id);
      });
    }
  },

  onAdded(node) {
    this.forEachId(node, id => {
      const el = document.querySelector('.msg[data-message-id="' + id + '"]');
      if (el) this.capture(id, el);
    });
  },

  onRemoved(node) {
    this.forEachId(node, id => {
      if (!this._delay) this._delay = {};
      clearTimeout(this._delay[id]);
      this._delay[id] = setTimeout(() => {
        if (document.querySelector('.msg[data-message-id="' + id + '"]')) return;
        const d = this.store();
        if (d[id] && d[id].del && d[id].ch === this.currentChannelId()) { this.paintGhosts(); return; }
        if (d[id] && d[id].ch && d[id].ch === this.currentChannelId()) this.markDeleted(id);
      }, 500);
    });
  },

  ensureUI() {
    if (document.getElementById('yapplus-mlog-btn')) return;
    const btn = document.createElement('button');
    btn.id = 'yapplus-mlog-btn';
    btn.textContent = 'MSG LOG';
    btn.style.cssText = 'position:fixed;right:16px;bottom:70px;z-index:2147483646;background:#1e1f22;color:#ff4b4b;border:1px solid rgba(255,75,75,0.5);border-radius:6px;padding:7px 12px;font-size:12px;font-weight:700;cursor:pointer;letter-spacing:0.5px;';
    btn.addEventListener('click', () => {
      const p = document.getElementById('yapplus-mlog-panel');
      if (!p) return;
      const open = p.style.display !== 'none';
      p.style.display = open ? 'none' : 'block';
      localStorage.setItem('yapplus.mlog.open', open ? '0' : '1');
    });

    const panel = document.createElement('div');
    panel.id = 'yapplus-mlog-panel';
    panel.style.cssText = 'position:fixed;right:16px;bottom:110px;width:380px;max-height:55vh;overflow-y:auto;z-index:2147483646;background:#111214;border:1px solid rgba(255,75,75,0.35);border-radius:8px;padding:8px;display:none;font-size:13px;';
    if (localStorage.getItem('yapplus.mlog.open') === '1') panel.style.display = 'block';

    document.body.appendChild(btn);
    document.body.appendChild(panel);
    this.render();
  },

  render() {
    const panel = document.getElementById('yapplus-mlog-panel');
    if (!panel) return;
    const ch = this.currentChannelId();
    const d = this.store();
    const rows = Object.values(d)
      .filter(r => r && r.ch === ch)
      .sort((a, b) => b.t - a.t);
    if (!rows.length) {
      panel.innerHTML = '<div style="color:#72767d;padding:6px;">No messages logged in this channel yet.</div>';
      return;
    }
    panel.innerHTML = rows.map(r => {
      const esc = String(r.content || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
      const name = String(r.name || 'unknown').replace(/</g, '&lt;');
      const av = r.pfp
        ? '<img src="' + String(r.pfp).replace(/"/g, '&quot;') + '" style="width:24px;height:24px;border-radius:50%;object-fit:cover;flex:none;">'
        : '<div style="width:24px;height:24px;border-radius:50%;background:#ff4b4b;color:#fff;font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center;flex:none;">' + (name[0] || '?').toUpperCase() + '</div>';
      const delTag = r.del ? '<b style="color:#ff4b4b;">[deleted]</b> ' : '';
      const delStyle = r.del ? 'background:rgba(255,75,75,0.08);border-left:2px solid #ff4b4b;' : 'border-left:2px solid transparent;';
      return '<div style="display:flex;gap:8px;padding:6px 8px;margin-bottom:4px;border-radius:4px;' + delStyle + '">' +
        av +
        '<div style="min-width:0;"><div style="display:flex;gap:6px;align-items:baseline;">' +
        '<b style="color:' + (r.del ? '#ff4b4b' : '#e3e5e8') + ';">' + name + '</b>' +
        '<span style="color:#72767d;font-size:11px;">' + String(r.time || '') + '</span></div>' +
        '<div style="color:' + (r.del ? '#ff4b4b' : '#b5bac1') + ';word-break:break-word;">' + delTag + esc + '</div></div></div>';
    }).join('');
  },

  start() {
    const self = this;
    this._delay = {};

    let css = document.getElementById('yapplus-del-css');
    if (!css) {
      css = document.createElement('style');
      css.id = 'yapplus-del-css';
      document.head.appendChild(css);
    }

    this.ensureUI();

    document.querySelectorAll('.msg[data-message-id]').forEach(el => {
      const id = el.getAttribute('data-message-id');
      if (id) self.capture(id, el);
    });

    this._obs = new MutationObserver(muts => {
      for (const m of muts) {
        m.addedNodes && m.addedNodes.forEach(n => self.onAdded(n));
        m.removedNodes && m.removedNodes.forEach(n => self.onRemoved(n));
      }
    });
    this._obs.observe(document.body, { childList: true, subtree: true });

    this._timer = setInterval(() => {
      try {
        // live-capture any missed messages + refresh deleted css for elements still in DOM
        document.querySelectorAll('.msg[data-message-id]').forEach(el => {
          const id = el.getAttribute('data-message-id');
          if (id) self.capture(id, el);
        });
        const ch = self.currentChannelId();
        const d = self.store();
        const rules = [];
        for (const r of Object.values(d)) {
          if (r && r.del && r.ch === ch) {
            rules.push('.msg[data-message-id="' + r.id + '"] .msg-text, .msg[data-message-id="' + r.id + '"] .msg-text *, .msg[data-message-id="' + r.id + '"] .msg-author { color:#ff4b4b !important; }');
          }
        }
        css.textContent = rules.join('\n');
        self.paintGhosts();
        self.render();
      } catch (e) {}
    }, 1500);

    // suppress the site's "Message deleted" toast
    const killDeleteToasts = () => {
      document.querySelectorAll('.toast').forEach(t => {
        if (/delet/i.test(t.textContent || '')) t.remove();
      });
    };
    this._toastObs = new MutationObserver(killDeleteToasts);
    this._toastObs.observe(document.body, { childList: true, subtree: true });
    killDeleteToasts();

    console.log('[Messagelogger] armed (dom observer)');
  },

  stop() {
    if (this._obs) { this._obs.disconnect(); this._obs = null; }
    if (this._toastObs) { this._toastObs.disconnect(); this._toastObs = null; }
    if (this._timer) { clearInterval(this._timer); this._timer = null; }
    if (this._delay) { for (const k in this._delay) clearTimeout(this._delay[k]); this._delay = null; }
    const btn = document.getElementById('yapplus-mlog-btn');
    if (btn) btn.remove();
    const panel = document.getElementById('yapplus-mlog-panel');
    if (panel) panel.remove();
    const css = document.getElementById('yapplus-del-css');
    if (css) css.remove();
    console.log('[Messagelogger] disarmed');
  },
};
